#include <stdio.h>
int countBits(int n) {
  int count = 0;
  while (n > 0) {
    count += n & 1;
    n >>= 1;
  }
  return count;
}
int main(void) {
  int number = 173;
  printf("%d", countBits(number));
  return 0;
}

import java.util.function.BiFunction;

public class Main {
    static int safeDiv(BiFunction<Integer, Integer, Integer> f, int a, int b) {
        try {
            return f.apply(a, b);
        } catch (ArithmeticException e) {
            return -1;
        }
    }
    public static void main(String[] args) {
        BiFunction<Integer, Integer, Integer> div = (x, y) -> x / y;
        int r1 = safeDiv(div, 10, 2);
        int r2 = safeDiv(div, 5, 0);
        System.out.print(r1 + r2);
    }
}

