int digitSum(int n){
  if(n==0) return 0;
  return n%10 + digitSum(n/10);
}
int main(){
  printf("%d", digitSum(12345));
}

#include <stdio.h>
#define SIZE 5

typedef struct {
    int a[SIZE];
    int top;
} Stack;

void push(Stack* s, int val) {
    s->a[++(s->top)] = val;
}

int pop(Stack* s) {
    return s->a[(s->top)--];
}

int main() {
    Stack s = { {0}, -1 };
    push(&s, 3); push(&s, 7); push(&s, 2);
    int a = pop(&s);
    push(&s, 9);
    int b = pop(&s);
    int c = pop(&s);
    printf("%d %d %d", a, b, c);
    return 0;
}

def shift_encode(s):
    result = ''
    for ch in s:
        if ch.isalpha():
            base = ord('a') if ch.islower() else ord('A')
            result += chr((ord(ch) - base + 1) % 26 + base)
        else:
            result += ch
    return result

word = "hello"
print(shift_encode(word))

public class Main {
  static int fib(int n) {
    if (n <= 1) return n;
    return fib(n-1) + fib(n-2);
  }
  public static void main(String[] args) {
    System.out.print(fib(7));
  }
